// --- AUTH HELPER ---
// Verifies the caller's real Supabase session token (sent as
// "Authorization: Bearer <token>") rather than trusting a client-
// supplied user id, which anyone could fake. Returns the verified user
// object or null. Every valuation-engine route below uses this — it's
// the actual security boundary between "user asking about their own
// credits" and "user claiming to be someone else to drain their
// credits or dodge the paywall."
async function getVerifiedUser(req) {
  if (!supabaseAdmin) return { user: null, reason: 'Supabase admin client not configured.' };
  const authHeader = req.headers.authorization || '';
  const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token || token === 'null' || token === 'undefined') {
    return { user: null, reason: 'No valid auth token was sent with the request.' };
  }
  const { data, error } = await supabaseAdmin.auth.getUser(token);
  if (error) {
    console.error('Supabase token verification failed:', error.message);
    return { user: null, reason: `Supabase rejected the token: ${error.message}` };
  }
  if (!data?.user) return { user: null, reason: 'Token verification returned no user.' };
  return { user: data.user, reason: null };
}

// --- AI VEHICLE VALUATION ENGINE ---
// Free trial + paid credits, tied to the real authenticated user (see
// 26_ai_valuation_engine.sql for why — not IP/session, both of which
// are trivially reset by anyone trying to get unlimited free trials).

// Same admin account already used throughout index.html for admin
// panel access — gets a standing 5-credit testing allowance instead of
// the normal single free trial.
const ADMIN_EMAIL = 'rafaloolivier1@gmail.com';
const ADMIN_FREE_CREDITS = 5;

// Looks up (creating if needed) a user's credit row. First-ever lookup
// grants their free trial credit automatically — 1 for everyone, 5 for
// the admin account. For the admin specifically, credits are also
// topped back up to 5 on every check if they've ever dropped below
// that, so it acts as a standing testing allowance rather than a
// one-time grant that runs out and needs manual SQL to refill.
async function getOrCreateCredits(userId, email) {
  const isAdmin = email === ADMIN_EMAIL;
  const initialCredits = isAdmin ? ADMIN_FREE_CREDITS : 1;

  // Atomic upsert instead of "select, then insert if missing" — that
  // check-then-act pattern has a real race condition: two nearly-
  // simultaneous requests (which this endpoint does get, in practice)
  // can both see "no row yet" before either finishes inserting, and the
  // second one then collides with the first. ignoreDuplicates makes
  // Postgres resolve this atomically instead.
  const { error: upsertError } = await supabaseAdmin
    .from('valuation_credits')
    .upsert({ user_id: userId, credits: initialCredits }, { onConflict: 'user_id', ignoreDuplicates: true });
  if (upsertError) throw upsertError;

  const { data, error } = await supabaseAdmin
    .from('valuation_credits')
    .select('*')
    .eq('user_id', userId)
    .single();
  if (error) throw error;

  if (isAdmin && data.credits < ADMIN_FREE_CREDITS) {
    const { data: topped, error: topUpError } = await supabaseAdmin
      .from('valuation_credits')
      .update({ credits: ADMIN_FREE_CREDITS })
      .eq('user_id', userId)
      .select()
      .single();
    if (topUpError) throw topUpError;
    return topped;
  }

  return data;
}

app.post('/api/valuation/check-access', async (req, res) => {
  if (!supabaseAdmin) return res.status(503).json({ error: 'Valuation engine is not configured — SUPABASE_SERVICE_ROLE_KEY is missing from the server environment.' });
  const { user, reason } = await getVerifiedUser(req);
  if (!user) return res.status(401).json({ error: `Sign in required. (${reason})` });
  try {
    const credits = await getOrCreateCredits(user.id, user.email);
    res.json({ hasAccess: credits.credits > 0, creditsRemaining: credits.credits });
  } catch (err) {
    console.error('check-access error:', err.message);
    res.status(500).json({ error: `Could not check valuation access: ${err.message}` });
  }
});

// Server-side source of truth for pack pricing — never trust a price or
// credit amount sent from the client, since that would let anyone just
// request a €0.01 charge for 10 credits by editing the request body.
const VALUATION_PACKS = {
  single:  { credits: 1,  amountCents: 299,  label: 'AI Vehicle Valuation — 1 use' },
  pack_5:  { credits: 5,  amountCents: 999,  label: 'AI Vehicle Valuation — 5-pack' },
  pack_10: { credits: 10, amountCents: 1499, label: 'AI Vehicle Valuation — 10-pack' },
};

app.post('/api/checkout/valuation-pass', async (req, res) => {
  if (!stripe) return res.status(503).json({ error: 'Payments are not configured — STRIPE_SECRET_KEY is missing from the server environment.' });
  const { user, reason } = await getVerifiedUser(req);
  if (!user) return res.status(401).json({ error: `Sign in required. (${reason})` });
  const packType = VALUATION_PACKS[req.body.pack_type] ? req.body.pack_type : 'single';
  const pack = VALUATION_PACKS[packType];
  try {
    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      payment_method_types: ['card'],
      client_reference_id: user.id,
      metadata: { pack_type: packType }, // read back in the webhook below to know how many credits to grant
      line_items: [{
        price_data: {
          currency: 'eur',
          product_data: { name: pack.label },
          unit_amount: pack.amountCents,
        },
        quantity: 1,
      }],
      success_url: `${process.env.APP_BASE_URL || 'http://localhost:' + port}/?valuation=success`,
      cancel_url: `${process.env.APP_BASE_URL || 'http://localhost:' + port}/?valuation=cancelled`,
    });
    res.json({ url: session.url });
  } catch (err) {
    console.error('checkout session error:', err.message);
    res.status(500).json({ error: `Could not start checkout: ${err.message}` });
  }
});

// Stripe webhook — this is the ONLY place credits get added from a
// payment. Uses req.rawBody (captured by the verify option on
// express.json() above), NOT req.body, since signature verification
// needs the exact original bytes Stripe signed, not a re-parsed object.
app.post('/api/webhook/stripe', async (req, res) => {
  if (!stripe || !process.env.STRIPE_WEBHOOK_SECRET) {
    return res.status(503).send('Webhook not configured.');
  }
  let event;
  try {
    event = stripe.webhooks.constructEvent(req.rawBody, req.headers['stripe-signature'], process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    console.error('Webhook signature verification failed:', err.message);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    const userId = session.client_reference_id;
    // Re-derive the credit amount from our own server-side pack table
    // using the pack_type read back from Stripe metadata — never trust
    // a credit count that could have come from the client.
    const packType = session.metadata?.pack_type;
    const pack = VALUATION_PACKS[packType] || VALUATION_PACKS.single;
    if (userId) {
      try {
        const credits = await getOrCreateCredits(userId);
        await supabaseAdmin
          .from('valuation_credits')
          .update({ credits: credits.credits + pack.credits, updated_at: new Date().toISOString() })
          .eq('user_id', userId);
      } catch (err) {
        console.error('Failed to credit user after payment:', err.message);
        // Still return 200 below — Stripe will retry on non-2xx, but a
        // DB failure here needs manual investigation, not an infinite
        // retry loop hammering the same broken write.
      }
    }
  }

  res.json({ received: true }); // Respond quickly; Stripe times out and retries otherwise.
});

// Computed in code, not by the AI — counting ratings is arithmetic, and
// arithmetic shouldn't be delegated to an LLM when it can just be
// computed correctly and reliably instead.
function computeDiagnosticScore(condition) {
  const values = Object.values(condition || {});
  const total = values.length;
  if (!total) return { good: 0, ok: 0, bad: 0, total: 0, percentage: 0 };
  const good = values.filter(v => v === 'Good').length;
  const ok = values.filter(v => v === 'OK').length;
  const bad = values.filter(v => v === 'Bad').length;
  const percentage = Math.round(((good * 100) + (ok * 50)) / total);
  return { good, ok, bad, total, percentage };
}

// Gemini occasionally returns 503 UNAVAILABLE ("high demand") — a
// known, common, and genuinely transient failure mode for LLM APIs,
// not a real error with the request itself. Retries several times with
// real exponential backoff (2s, 4s, 8s, 16s) specifically for that
// case, giving a demand spike substantially more time to clear before
// giving up — any other error (bad request, auth failure, etc.) is
// thrown immediately since retrying those would just waste time
// without ever succeeding.
async function callGeminiWithRetry(callFn, maxAttempts = 5) {
  let lastError;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await callFn();
    } catch (err) {
      lastError = err;
      const isRetryable = /UNAVAILABLE|503|high demand/i.test(err.message || '');
      if (!isRetryable || attempt === maxAttempts) throw err;
      const delayMs = Math.pow(2, attempt) * 1000; // 2s, 4s, 8s, 16s
      console.warn(`Gemini call failed (attempt ${attempt}/${maxAttempts}), retrying in ${delayMs}ms:`, err.message);
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
  }
  throw lastError;
}

// ═══════════════════════════════════════════════════════════════
// OCHRONA PRZED NADUŻYCIAMI: rate limiting na IP + Cloudflare Turnstile
// ═══════════════════════════════════════════════════════════════
// Limit wycen na IP w oknie czasowym (domyślnie 5 / 15 min). Licznik w pamięci
// procesu — wystarczy dla jednej instancji (Mikrus/VPS). Przy kilku instancjach
// lub restartach trzeba by użyć Redis. Limit jest zwalniany, jeśli wycena się
// nie powiodła (np. błąd AI, brak kredytów), więc użytkownik nie traci "slotu".
const VAL_RATE_MAX = parseInt(process.env.VALUATION_RATE_MAX || '5', 10);
const VAL_RATE_WINDOW_MS = parseInt(process.env.VALUATION_RATE_WINDOW_MIN || '15', 10) * 60 * 1000;
const VAL_ATTEMPT_MAX = VAL_RATE_MAX * 4; // twardy sufit na wszystkie próby (także nieudane), by nie spamować siteverify
const valRateHits = new Map();     // ip -> [timestamps udanych/rezerwowanych wycen]
const valAttemptHits = new Map();  // ip -> [timestamps wszystkich prób]

function pruneHits(map, ip, now) {
  const arr = (map.get(ip) || []).filter(t => now - t < VAL_RATE_WINDOW_MS);
  if (arr.length) map.set(ip, arr); else map.delete(ip);
  return arr;
}
setInterval(() => {
  const now = Date.now();
  for (const ip of [...valRateHits.keys()]) pruneHits(valRateHits, ip, now);
  for (const ip of [...valAttemptHits.keys()]) pruneHits(valAttemptHits, ip, now);
}, 5 * 60 * 1000).unref();

function rateLimitMessage(retryAfterSec) {
  const min = Math.ceil(retryAfterSec / 60);
  return `Przekroczono limit ${VAL_RATE_MAX} wycen na ${Math.round(VAL_RATE_WINDOW_MS / 60000)} minut z jednego adresu IP. Spróbuj ponownie za ok. ${min} min.`;
}

// Zwraca { ok:true, release() } albo { ok:false, retryAfterSec }.
function reserveValuationSlot(ip) {
  const now = Date.now();
  const attempts = pruneHits(valAttemptHits, ip, now);
  const hits = pruneHits(valRateHits, ip, now);
  const oldest = hits[0] ?? attempts[0] ?? now;
  if (hits.length >= VAL_RATE_MAX || attempts.length >= VAL_ATTEMPT_MAX) {
    return { ok: false, retryAfterSec: Math.max(1, Math.ceil((oldest + VAL_RATE_WINDOW_MS - now) / 1000)) };
  }
  attempts.push(now); valAttemptHits.set(ip, attempts);
  hits.push(now); valRateHits.set(ip, hits);
  return {
    ok: true,
    release() {
      const cur = valRateHits.get(ip) || [];
      const idx = cur.indexOf(now);
      if (idx !== -1) cur.splice(idx, 1);
      if (cur.length) valRateHits.set(ip, cur); else valRateHits.delete(ip);
    }
  };
}

// Weryfikacja tokenu Cloudflare Turnstile po stronie serwera.
// Brak TURNSTILE_SECRET_KEY = weryfikacja wyłączona (tylko lokalny development);
// ustaw REQUIRE_TURNSTILE=true na produkcji, by brak klucza blokował wyceny.
async function verifyTurnstile(token, ip) {
  const secret = process.env.TURNSTILE_SECRET_KEY;
  if (!secret) {
    if (process.env.REQUIRE_TURNSTILE === 'true') return { ok: false, error: 'Zabezpieczenie antybotowe nie jest skonfigurowane.' };
    console.warn('[turnstile] TURNSTILE_SECRET_KEY nie ustawiony — weryfikacja pominięta.');
    return { ok: true };
  }
  if (!token || typeof token !== 'string' || token.length > 2048) {
    return { ok: false, error: 'Potwierdź, że nie jesteś robotem (weryfikacja Turnstile).' };
  }
  try {
    const body = new URLSearchParams({ secret, response: token });
    if (ip) body.set('remoteip', ip);
    const r = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
      method: 'POST', body, signal: AbortSignal.timeout(8000)
    });
    const j = await r.json();
    if (j.success) return { ok: true };
    console.warn('[turnstile] odrzucono token:', (j['error-codes'] || []).join(','));
    return { ok: false, error: 'Weryfikacja antybotowa nie powiodła się. Odśwież stronę i spróbuj ponownie.' };
  } catch (e) {
    console.error('[turnstile] błąd siteverify:', e.message);
    return { ok: false, error: 'Nie udało się zweryfikować zabezpieczenia antybotowego. Spróbuj ponownie za chwilę.' };
  }
}

