// Lets a user see their own past valuation reports — RLS already
// restricts what a regular client could read here (users can SELECT
// only their own rows per 26_ai_valuation_engine.sql), but this uses
// the service role and explicitly filters by user_id anyway, as
// defense in depth rather than relying on RLS alone.
app.get('/api/valuation/history', async (req, res) => {
  if (!supabaseAdmin) return res.status(503).json({ error: 'Valuation engine is not configured — SUPABASE_SERVICE_ROLE_KEY is missing from the server environment.' });
  const { user, reason } = await getVerifiedUser(req);
  if (!user) return res.status(401).json({ error: `Sign in required. (${reason})` });
  try {
    const { data, error } = await supabaseAdmin
      .from('valuation_logs')
      .select('id, created_at, vehicle_details, ai_result')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false })
      .limit(50);
    if (error) throw error;
    const history = (data || []).map(log => ({
      id: log.id,
      createdAt: log.created_at,
      vehicle: `${log.vehicle_details?.brand || ''} ${log.vehicle_details?.model || ''}`.trim() || 'Unknown vehicle',
      year: log.vehicle_details?.year || null,
      estimatedPriceRange: log.ai_result?.estimatedPriceRange || null,
      scorePercentage: log.ai_result?.diagnosticScore?.percentage ?? null
    }));
    res.json({ history });
  } catch (err) {
    console.error('valuation history error:', err.message);
    res.status(500).json({ error: `Could not load valuation history: ${err.message}` });
  }
});

app.get('/api/valuation/pdf/:logId', async (req, res) => {
  if (!supabaseAdmin) return res.status(503).json({ error: 'Valuation engine is not configured.' });
  const { user, reason } = await getVerifiedUser(req);
  if (!user) return res.status(401).json({ error: `Sign in required. (${reason})` });

  try {
    const { data: log, error } = await supabaseAdmin
      .from('valuation_logs')
      .select('*')
      .eq('id', req.params.logId)
      .single();
    if (error || !log) return res.status(404).json({ error: 'Report not found.' });
    if (log.user_id !== user.id) return res.status(403).json({ error: 'This report does not belong to you.' });

    const v = log.vehicle_details || {};
    const r = log.ai_result || {};

    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="valuation-${log.id}.pdf"`);

    const doc = new PDFDocument({ margin: 0, size: 'A4', bufferPages: true });
    doc.pipe(res);

    const PAGE_W = doc.page.width;
    const MARGIN = 50;
    const CONTENT_W = PAGE_W - MARGIN * 2;

    // ── Header band ──
    doc.rect(0, 0, PAGE_W, 100).fill('#0c1a3a');
    try {
      // Logo po lewej, skalowane proporcjonalnie (fit) w polu 170x50 i wyśrodkowane w pionie w nagłówku (100 pt)
      const logoBuffer = Buffer.from(LOGO_BASE64, 'base64');
      const LOGO_BOX_W = 170, LOGO_BOX_H = 50;
      doc.image(logoBuffer, MARGIN, (100 - LOGO_BOX_H) / 2, {
        fit: [LOGO_BOX_W, LOGO_BOX_H], align: 'left', valign: 'center'
      });
    } catch (e) { /* logo is a nice-to-have — a report without it is still fine */ }
    doc.fillColor('#ffffff').fontSize(18).font('Helvetica-Bold').text(
      'AI Vehicle Valuation Report', PAGE_W - MARGIN - 260, 38, { width: 260, align: 'right' }
    );
    doc.fillColor('#cbd5e1').fontSize(9).font('Helvetica').text(
      new Date(log.created_at).toLocaleString(), PAGE_W - MARGIN - 260, 62, { width: 260, align: 'right' }
    );

    let y = 130;

    // ── Vehicle summary box ──
    doc.roundedRect(MARGIN, y, CONTENT_W, 70, 6).fillAndStroke('#f8fafc', '#e2e8f0');
    const vehLabel = (label, value, x, w) => {
      doc.fillColor('#64748b').fontSize(8).font('Helvetica-Bold').text(label.toUpperCase(), x, y + 12, { width: w });
      doc.fillColor('#0f172a').fontSize(12).font('Helvetica-Bold').text(value || '—', x, y + 26, { width: w });
    };
    const colW = CONTENT_W / 4;
    vehLabel('Vehicle', `${v.brand || ''} ${v.model || ''}`.trim(), MARGIN + 16, colW * 1.4);
    vehLabel('Year', v.year, MARGIN + colW * 1.6, colW * 0.6);
    vehLabel('Mileage', v.mileageKm ? `${v.mileageKm} km` : null, MARGIN + colW * 2.2, colW * 0.8);
    vehLabel('Claimed Price', v.claimedPrice, MARGIN + colW * 3, colW * 0.9);
    y += 90;

    // ── Headline boxes: score + estimated value, side by side ──
    const boxW = (CONTENT_W - 16) / 2;
    if (r.diagnosticScore) {
      const scoreColor = r.diagnosticScore.percentage >= 70 ? '#16a34a' : r.diagnosticScore.percentage >= 40 ? '#d97706' : '#dc2626';
      doc.roundedRect(MARGIN, y, boxW, 80, 6).fillAndStroke('#ffffff', '#e2e8f0');
      doc.fillColor('#64748b').fontSize(8).font('Helvetica-Bold').text('OVERALL DIAGNOSTIC SCORE', MARGIN + 16, y + 14);
      doc.fillColor(scoreColor).fontSize(28).font('Helvetica-Bold').text(`${r.diagnosticScore.percentage}%`, MARGIN + 16, y + 28);
      doc.fillColor('#64748b').fontSize(8).font('Helvetica').text(
        `${r.diagnosticScore.good} Good · ${r.diagnosticScore.ok} OK · ${r.diagnosticScore.bad} Bad`, MARGIN + 16, y + 62
      );
    }
    doc.roundedRect(MARGIN + boxW + 16, y, boxW, 80, 6).fillAndStroke('#0c1a3a', '#0c1a3a');
    doc.fillColor('#94a3b8').fontSize(8).font('Helvetica-Bold').text('ESTIMATED REAL TRANSACTION VALUE', MARGIN + boxW + 32, y + 14, { width: boxW - 32 });
    doc.fillColor('#ffffff').fontSize(20).font('Helvetica-Bold').text(r.estimatedPriceRange || '—', MARGIN + boxW + 32, y + 34, { width: boxW - 32 });
    y += 100;

    // ── Checklist results ──
    doc.fillColor('#0c1a3a').fontSize(13).font('Helvetica-Bold').text('Inspection Checklist Results', MARGIN, y);
    y += 20;
    const condition = v.condition || {};
    let anyRated = false;
    PDF_CHECKLIST_LABELS.forEach(cat => {
      const catItems = cat.items.filter(i => condition[i.id]);
      if (!catItems.length) return;
      anyRated = true;
      if (y > doc.page.height - 100) { doc.addPage(); y = MARGIN; }
      doc.fillColor('#0ea5e9').fontSize(10.5).font('Helvetica-Bold').text(cat.category, MARGIN, y);
      y += 16;
      catItems.forEach(i => {
        if (y > doc.page.height - 60) { doc.addPage(); y = MARGIN; }
        const rating = condition[i.id];
        const color = rating === 'Good' ? '#16a34a' : rating === 'OK' ? '#d97706' : '#dc2626';
        doc.fillColor('#334155').fontSize(9.5).font('Helvetica').text(i.label, MARGIN + 12, y, { width: CONTENT_W - 90, continued: false });
        doc.fillColor(color).fontSize(9.5).font('Helvetica-Bold').text(rating, PAGE_W - MARGIN - 60, y, { width: 60, align: 'right' });
        y += 15;
      });
      y += 8;
    });
    if (!anyRated) {
      doc.fillColor('#64748b').fontSize(10).font('Helvetica').text('No items were rated on the checklist before this report was generated.', MARGIN, y);
      y += 20;
    }
    y += 10;

    // ── Repair costs ──
    if (y > doc.page.height - 150) { doc.addPage(); y = MARGIN; }
    doc.fillColor('#0c1a3a').fontSize(13).font('Helvetica-Bold').text('Itemized Repair Cost Estimate', MARGIN, y);
    y += 20;
    const items = Array.isArray(r.itemizedRepairCosts) ? r.itemizedRepairCosts : [];
    if (items.length) {
      items.forEach(i => {
        if (y > doc.page.height - 60) { doc.addPage(); y = MARGIN; }
        doc.fillColor('#334155').fontSize(10).font('Helvetica').text(`•  ${i.item}`, MARGIN + 4, y, { width: CONTENT_W - 100 });
        doc.fillColor('#0f172a').fontSize(10).font('Helvetica-Bold').text(i.estimatedCost, PAGE_W - MARGIN - 100, y, { width: 100, align: 'right' });
        y += 16;
      });
    } else {
      doc.fillColor('#64748b').fontSize(10).font('Helvetica').text('No repair items flagged — condition ratings given did not indicate outstanding issues.', MARGIN, y, { width: CONTENT_W });
      y += 20;
    }
    y += 14;

    // ── Reasoning ──
    if (y > doc.page.height - 120) { doc.addPage(); y = MARGIN; }
    doc.fillColor('#0c1a3a').fontSize(11).font('Helvetica-Bold').text('Reasoning', MARGIN, y);
    y += 16;
    doc.fillColor('#475569').fontSize(9.5).font('Helvetica').text(r.justification || '', MARGIN, y, { width: CONTENT_W, lineGap: 3 });

    // ── Footer on every page ──
    const FOOTER_NOTICE = 'Raport wygenerowany automatycznie przez AutoEncyklopedia. Wycena ma charakter wyłącznie szacunkowy i informacyjny.';
    let footerFont = 'Helvetica';
    try {
      doc.registerFont('FooterFont', Buffer.from(FOOTER_FONT_BASE64, 'base64'));
      footerFont = 'FooterFont';
    } catch (e) { /* fallback: Helvetica (bez polskich znaków diakrytycznych) */ }
    const pageRange = doc.bufferedPageRange();
    for (let i = 0; i < pageRange.count; i++) {
      doc.switchToPage(i);
      const footerY = doc.page.height - 40;
      doc.rect(MARGIN, footerY, CONTENT_W, 0.5).fill('#e2e8f0');
      doc.fillColor('#94a3b8').fontSize(6.5).font(footerFont).text(
        FOOTER_NOTICE, MARGIN, footerY + 8, { width: CONTENT_W - 60, lineBreak: true }
      );
      doc.fillColor('#94a3b8').fontSize(7).font('Helvetica').text(
        `${i + 1} / ${pageRange.count}`, PAGE_W - MARGIN - 40, footerY + 8, { width: 40, lineBreak: false, align: 'right' }
      );
    }

    doc.end();
  } catch (err) {
    console.error('PDF generation error:', err.message);
    if (!res.headersSent) res.status(500).json({ error: `Could not generate PDF: ${err.message}` });
  }
});

// --- AI CAR FINDER (knowledge-based, no external redirection) ---
// The AI recommends real-world car MODELS from its own automotive
// knowledge (not a live inventory search) matching the buyer's budget,
// seats, features, and usage. Price ranges here are general/approximate
// — this is the model's training knowledge, not live market data — the
// frontend labels them accordingly rather than presenting them as
// current pricing. The API key stays server-side; the client only ever
// sees this endpoint's JSON response.
//
// Whether a recommended model is actually in Autoencyklopedia's own
// catalog is deliberately NOT decided by Gemini here — that check is a
// real, separate Supabase lookup done on the frontend after this
// response comes back. Asking an LLM to self-report a precise database
// ID match from a list embedded in its prompt risks it getting a match
// wrong, which would silently produce a broken or incorrect "View
// In-House Inspection" link — a real query can't hallucinate that.
// --- ADMIN AI-ASSISTED "CARS TO AVOID" ENTRY BUILDER ---
// Admin pastes raw, unstructured text (an article excerpt, forum post,
// review, etc.) about a car model; Gemini structures it into the fields
// the avoid_list_entries table expects. This is a DRAFT for the admin
// to review and edit — nothing is saved here. The actual save happens
// as a separate, plain Supabase insert from the frontend (same pattern
// as every other admin-editable catalog table in this app — groups,
// brands, vehicles, engines all save directly via supabaseClient with
// RLS as the real security boundary, not through a backend route).
//
// Gated to the admin specifically, not just "any signed-in user" — this
// costs a real Gemini API call each time, and there's no legitimate
// reason for a non-admin account to be hitting an endpoint that only
// feeds an admin-only save flow.
app.post('/api/admin/avoid-list/parse', async (req, res) => {
  if (!genAI) return res.status(503).json({ error: 'AI parsing is not configured — GEMINI_API_KEY is missing from the server environment.' });
  const { user, reason } = await getVerifiedUser(req);
  if (!user) return res.status(401).json({ error: `Sign in required. (${reason})` });
  if (user.email !== ADMIN_EMAIL) return res.status(403).json({ error: 'Admin access required.' });

  const { rawText } = req.body;
  if (!rawText || !rawText.trim()) return res.status(400).json({ error: 'No text provided to parse.' });

  const prompt = `You are a structured-data extraction assistant for Autoencyklopedia, an automotive encyclopedia. You will be given raw, unstructured text about a specific car model — this could be an article excerpt, a forum post, an owner review, or similar. Extract and structure the following, using ONLY what the text actually supports plus your own general automotive knowledge to fill reasonable gaps — never invent a specific defect or number that has no basis in the text or in real-world knowledge of this model:

- make: the vehicle manufacturer (e.g. "Alfa Romeo")
- model: the specific model, and generation/engine variant if mentioned (e.g. "159 2.4 JTD")
- commonDefects: an array of general, factory-level defects or design weaknesses mentioned or clearly implied by the text (e.g. "Poor rust protection on early production years") — broader, structural issues, not specific failed-part incidents
- knownIssues: an array of specific mechanical/electrical failure points (e.g. "Turbo failure around 150,000-180,000 km", "EGR valve clogging causes rough idle") — distinct from commonDefects, which are broader design-level weaknesses
- estimatedRepairCosts: an array of {issue, cost} objects, one per major known issue, with a realistic approximate cost range in EUR (e.g. "€800-1,200") based on typical European independent-garage rates for this kind of repair — only include costs for issues you're reasonably confident about, don't pad the list
- verdict: either "avoid" or "worth_considering" — your overall judgment based on the severity and cost of the issues described, weighed against the text's overall tone
- reasoning: one or two sentences summarizing why, suitable as a short card caption (matching the tone of: "Persistent turbo, EGR, and head gasket failures. Repair costs often exceed the car's value.")

If the text doesn't clearly identify a specific make and model, do your best with what's given but note the uncertainty in the reasoning field rather than guessing confidently.

Raw text to analyze:
"""
${rawText}
"""`;

  try {
    const response = await callGeminiWithRetry(() => genAI.models.generateContent({
      model: 'gemini-3.6-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            make: { type: Type.STRING },
            model: { type: Type.STRING },
            commonDefects: { type: Type.ARRAY, items: { type: Type.STRING } },
            knownIssues: { type: Type.ARRAY, items: { type: Type.STRING } },
            estimatedRepairCosts: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  issue: { type: Type.STRING },
                  cost: { type: Type.STRING },
                },
                required: ['issue', 'cost'],
              },
            },
            verdict: { type: Type.STRING },
            reasoning: { type: Type.STRING },
          },
          required: ['make', 'model', 'commonDefects', 'knownIssues', 'estimatedRepairCosts', 'verdict', 'reasoning'],
        },
      },
    }));
    const parsed = JSON.parse(response.text);
    // Defensive normalization — an LLM occasionally returns something
    // slightly off-schema despite the responseSchema constraint (e.g. a
    // verdict value with different casing); this doesn't trust it blindly.
    parsed.verdict = parsed.verdict === 'worth_considering' ? 'worth_considering' : 'avoid';
    res.json({ parsed });
  } catch (err) {
    console.error('avoid-list parse error:', err.message);
    res.status(500).json({ error: `Could not parse text: ${err.message}` });
  }
});

app.post('/api/ai-recommendations', async (req, res) => {
  if (!genAI) {
    return res.status(503).json({ error: 'AI assistant is not configured — GEMINI_API_KEY is missing from the server environment.' });
  }
  const { answers } = req.body;
  if (!answers) {
    return res.status(400).json({ error: 'No buyer preferences provided.' });
  }

  const prompt = `You are Gemini — Official Autoencyklopedia AI Advisor. A buyer gave these preferences:
- Budget: ${answers?.budget?.label || 'not specified'}
- Seats needed: ${answers?.seats || 'not specified'}
- Must-have features: ${(answers?.features || []).join(', ') || 'none specified'}
- Primary usage: ${answers?.usage || 'not specified'}
- Preferred body style: ${answers?.bodyStyle || 'no preference'}

Using your general automotive knowledge, recommend 3 to 5 REAL, well-known car models (never invent a fictional model) that reasonably fit this budget and these criteria. For each recommendation:
- brand
- model (include generation/trim where it matters, e.g. "A4 B8 Allroad")
- yearRange (e.g. "2009–2012")
- matchedFeatures: which of the buyer's requested features this model is actually known for (don't claim a feature it doesn't have)
- priceRange: an approximate typical used-market price range for this budget context, clearly a general estimate (e.g. "roughly $12,000–$16,000")`;

  try {
    const response = await callGeminiWithRetry(() => genAI.models.generateContent({
      model: 'gemini-3.6-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            recommendations: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  brand: { type: Type.STRING },
                  model: { type: Type.STRING },
                  yearRange: { type: Type.STRING },
                  matchedFeatures: { type: Type.ARRAY, items: { type: Type.STRING } },
                  priceRange: { type: Type.STRING },
                },
                required: ['brand', 'model', 'yearRange', 'matchedFeatures', 'priceRange'],
              },
            },
          },
          required: ['recommendations'],
        },
      },
    }));
    const parsed = JSON.parse(response.text);
    res.json(parsed);
  } catch (err) {
    console.error('AI car finder error:', err.message);
    res.status(500).json({ error: `AI search failed: ${err.message}` });
  }
});

app.listen(port, 'localhost', () => {
  const url = `http://localhost:${port}`;
  console.log(`Your server is running on port ${port}`);
  console.log(url);

  // Auto-open the browser on start. Uses each OS's own built-in command
  // (no extra npm package needed) — 'open' on macOS, 'start' on Windows,
  // 'xdg-open' on Linux.
  const openCommand =
    process.platform === 'darwin' ? `open ${url}` :
    process.platform === 'win32' ? `start ${url}` :
    `xdg-open ${url}`;
  exec(openCommand, (err) => {
    if (err) console.log('Could not auto-open the browser — just open the link above manually.');
  });
});